    if (queueCb->queue == NULL)
    {
        return OS_ERRNO_QUEUE_CREATE_NO_MEMORY;
    }

    for (index = 0; index < nodeNum; index++)
    {
        queueNode = (struct QueNode *)(uintptr_t)&queueCb->queue[index * nodeSize];
        queueNode->srcPid = OS_QUEUE_PID_INVALID;
    }

